// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createCollection, createLink, createHighlight, updateHighlight, getHighlights, deleteLink, deleteCollection } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Request Body
    const collectionsPostRequestBody: string = `{
        "name": "Highlights Patch Happy"
    }`;

    // Request Body
    const linksPostRequestBody: string = `{
        "collection": {
            "id": 411
        },
        "name": "Highlights Patch Source",
        "tags": [],
        "type": "url",
        "url": "https://example.com/hl-patch"
    }`;

    // Request Body
    const highlightsPostRequestBody: string = `{
        "color": "yellow",
        "comment": "original note",
        "endOffset": 17,
        "linkId": 422,
        "startOffset": 0,
        "text": "Patchable passage"
    }`;

    // Request Body
    const highlightsHighlightsPatchRequestBody: string = `{
        "comment": "revised note"
    }`;

    // Request Body
    const highlightsHighlightsPatch1RequestBody: string = `{
        "color": "red"
    }`;

    const collectionsPostResponse = await createCollection(client, URL_localhost, headers, collectionsPostRequestBody);
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsPostResponse, "response.name"), 'collection name').toBe("Highlights Patch Happy");
    expect(getResponseValue(collectionsPostResponse, "response.id"), 'collection id').toBeGreaterThan(0);
    const linksPostResponse = await createLink(client, URL_localhost, headers, linksPostRequestBody, {"collection.id": getResponseValue(collectionsPostResponse, "response.id")});
    expect(linksPostResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksPostResponse, "response.name"), 'link name').toBe("Highlights Patch Source");
    expect(getResponseValue(linksPostResponse, "response.url"), 'link url').toBe("https://example.com/hl-patch");
    expect(getResponseValue(linksPostResponse, "response.collectionId"), 'link collection').toBe(getResponseValue(collectionsPostResponse, "response.id"));
    const highlightsPostResponse = await createHighlight(client, URL_localhost, headers, highlightsPostRequestBody, {"linkId": getResponseValue(linksPostResponse, "response.id")});
    expect(highlightsPostResponse.statusCode, 'status code').toBe(200);
    const highlightId = getResponseValue(highlightsPostResponse, "response.id");
    expect(getResponseValue(highlightsPostResponse, "response.color"), 'created colour').toBe("yellow");
    expect(getResponseValue(highlightsPostResponse, "response.comment"), 'created comment').toBe("original note");
    expect(getResponseValue(highlightsPostResponse, "response.text"), 'created text').toBe("Patchable passage");
    expect(getResponseValue(highlightsPostResponse, "response.linkId"), 'created highlight link').toBe(getResponseValue(linksPostResponse, "response.id"));

    const highlightsHighlightsPatchResponse = await updateHighlight(client, URL_localhost, headers, highlightId, highlightsHighlightsPatchRequestBody);
    expect(highlightsHighlightsPatchResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsHighlightsPatchResponse, "response.id"), 'patched the same highlight').toBe(highlightId);
    expect(getResponseValue(highlightsHighlightsPatchResponse, "response.comment"), 'comment updated').toBe("revised note");
    expect(getResponseValue(highlightsHighlightsPatchResponse, "response.color"), 'colour untouched by a comment-only patch').toBe("yellow");
    expect(getResponseValue(highlightsHighlightsPatchResponse, "response.text"), 'text untouched').toBe("Patchable passage");
    expect(getResponseValue(highlightsHighlightsPatchResponse, "response.link.id"), 'link attached to the patch response').toBe(getResponseValue(linksPostResponse, "response.id"));
    expect(getResponseValue(highlightsHighlightsPatchResponse, "response.link.name"), 'link name attached').toBe("Highlights Patch Source");
    expect(getResponseValue(highlightsHighlightsPatchResponse, "response.link.url"), 'link url attached').toBe("https://example.com/hl-patch");

    const highlightsHighlightsPatch1Response = await updateHighlight(client, URL_localhost, headers, highlightId, highlightsHighlightsPatch1RequestBody);
    expect(highlightsHighlightsPatch1Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsHighlightsPatch1Response, "response.id"), 'patched the same highlight').toBe(highlightId);
    expect(getResponseValue(highlightsHighlightsPatch1Response, "response.color"), 'colour updated').toBe("red");
    expect(getResponseValue(highlightsHighlightsPatch1Response, "response.comment"), 'comment untouched by a colour-only patch').toBe("revised note");

    const highlightsGetResponse = await getHighlights(client, URL_localhost, headers, {"color": ["red"]});
    expect(highlightsGetResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsGetResponse, "response.highlights").length, 'the patched highlight is the only red one').toBe(1);
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.id"), 'both edits persisted').toBe(highlightId);
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.color"), 'persisted colour').toBe("red");
    expect(getResponseValue(highlightsGetResponse, "response.highlights.0.comment"), 'persisted comment').toBe("revised note");
    expect(getResponseValue(highlightsGetResponse, "response.highlights.1"), 'no other red highlight').toBeNull();

    const linksLinksDeleteResponse = await deleteLink(client, URL_localhost, headers, getResponseValue(linksPostResponse, "response.id"));
    expect(linksLinksDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'deleted link').toBe(getResponseValue(linksPostResponse, "response.id"));
    const collectionsCollectionsDeleteResponse = await deleteCollection(client, URL_localhost, headers, getResponseValue(collectionsPostResponse, "response.id"));
    expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(collectionsCollectionsDeleteResponse, "response.id"), 'deleted collection').toBe(getResponseValue(collectionsPostResponse, "response.id"));
});
